#!/bin/bash

# Auto-Build Environment Setup
# Generated by Planner Agent for: Split GameScreen.tsx into focused component modules

set -e

echo "========================================"
echo "Starting Development Environment"
echo "========================================"

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

# Wait for service function
wait_for_service() {
    local port=$1
    local name=$2
    local max=30
    local count=0

    echo "Waiting for $name on port $port..."
    while ! nc -z localhost $port 2>/dev/null; do
        count=$((count + 1))
        if [ $count -ge $max ]; then
            echo -e "${RED}$name failed to start${NC}"
            return 1
        fi
        sleep 1
    done
    echo -e "${GREEN}$name ready${NC}"
}

# ============================================
# START SERVICES
# ============================================

echo ""
echo "Starting Expo Development Server..."
echo ""

# Navigate to project root (parent of .auto-claude)
cd "$(dirname "$0")/../../.."

# Start Expo development server
npm start &

# Wait for Expo to be ready
wait_for_service 8081 "Expo Metro Bundler"

# ============================================
# SUMMARY
# ============================================

echo ""
echo "========================================"
echo "Environment Ready!"
echo "========================================"
echo ""
echo "Services:"
echo "  Expo Metro:  http://localhost:8081"
echo "  Web:         http://localhost:8081"
echo ""
echo "To test on device:"
echo "  - iOS Simulator: Press 'i' in terminal"
echo "  - Android Emulator: Press 'a' in terminal"
echo "  - Physical Device: Scan QR code with Expo Go app"
echo ""
echo "Files to modify:"
echo "  - src/screens/GameScreen.tsx (refactor target)"
echo ""
echo "Files to create:"
echo "  - src/components/game-ui/*.tsx (10 new components)"
echo ""
